SELECT d.id, d.knowledge_base_id, d.name, d.file_path, d.status, d.create_time, d.update_time, d.is_deleted FROM knowledge_document d JOIN knowledge_base kb ON d.knowledge_base_id = kb.id
(d.is_deleted = 0 OR d.is_deleted IS NULL) AND (kb.is_deleted = 0 OR kb.is_deleted IS NULL)
AND kb.owner_id = #{userId}
AND d.knowledge_base_id IN
#{kbId}
AND d.status = CASE WHEN #{status} = 1 THEN 'processing' WHEN #{status} = 2 THEN 'completed' WHEN #{status} = 3 THEN 'failed' ELSE 'processing' END
ORDER BY d.${sortColumn} ${direction} LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(d.id) FROM knowledge_document d JOIN knowledge_base kb ON d.knowledge_base_id = kb.id
(d.is_deleted = 0 OR d.is_deleted IS NULL) AND (kb.is_deleted = 0 OR kb.is_deleted IS NULL)
AND kb.owner_id = #{userId}
AND d.knowledge_base_id IN
#{kbId}
AND d.status = CASE WHEN #{status} = 1 THEN 'processing' WHEN #{status} = 2 THEN 'completed' WHEN #{status} = 3 THEN 'failed' ELSE 'processing' END
